INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5797987, 845018, 80904, '<td valign="top">oh man, I would love to see this one Ribbon. Did you tell Andrea that her photo was on this challenge? she woudl be super happy to know that ;)</td>', 'oh man, I would love to see this one Ribbon. Did you tell Andrea that her photo was on this challenge? she woudl be super happy to know that ;)', '2010-01-06 00:07:30.000000', NULL, 1),
(5798043, 844963, 52336, '<td valign="top">I must be honest -- this is not as impacting a portrait for me as you probably think it should be, and I''m not as engaged with the subject as I''d like.  But the light... my god, the light.  It''s beautiful.  Everything from the way you''ve arranged it on the backdrop to the drama on his face is quite perfect for me.  Well done.  You have issues with haloing around the sax, and I believe I see wrinkles on the backdrop, but nice job on the light.  8</td>', 'I must be honest -- this is not as impacting a portrait for me as you probably think it should be, and I''m not as engaged with the subject as I''d like.  But the light... my god, the light.  It''s beautiful.  Everything from the way you''ve arranged it on the backdrop to the drama on his face is quite perfect for me.  Well done.  You have issues with haloing around the sax, and I believe I see wrinkles on the backdrop, but nice job on the light.  8', '2010-01-06 00:45:58.000000', NULL, 1),
(5798045, 842856, 52336, '<td valign="top">Wow, what a laugh that gave me. :) 6 for that.</td>', 'Wow, what a laugh that gave me. :) 6 for that.', '2010-01-06 00:46:30.000000', NULL, 1),
(5798049, 844335, 52336, '<td valign="top">Photographically not perfect, but what a concept!  Nicely thought out.  (What a beauty she was.)  6</td>', 'Photographically not perfect, but what a concept!  Nicely thought out.  (What a beauty she was.)  6', '2010-01-06 00:48:06.000000', NULL, 1),
(5798053, 844911, 52336, '<td valign="top">Indeed.  Nicely taken.  7</td>', 'Indeed.  Nicely taken.  7', '2010-01-06 00:48:52.000000', NULL, 1),
(5798062, 844062, 52336, '<td valign="top">I would have been crazy about this if it had been a little more technically thought out... for one thing, just a bit too soft, and something has been done on the right side (his left) to sharpen?  Or something?  Some odd anomaly there.  He makes an engaging portrait, though, and other elements, such as the lighting, are very good, but something technically wrong with this makes it less than perfect for me.  Too bad, so much potential. 6</td>', 'I would have been crazy about this if it had been a little more technically thought out... for one thing, just a bit too soft, and something has been done on the right side (his left) to sharpen?  Or something?  Some odd anomaly there.  He makes an engaging portrait, though, and other elements, such as the lighting, are very good, but something technically wrong with this makes it less than perfect for me.  Too bad, so much potential. 6', '2010-01-06 00:51:25.000000', NULL, 1),
(5798064, 844168, 52336, '<td valign="top">I just think it''s too much with the sharpening on his face.  Would have been really good if more restrained. 6</td>', 'I just think it''s too much with the sharpening on his face.  Would have been really good if more restrained. 6', '2010-01-06 00:52:02.000000', NULL, 1),
(5798083, 844661, 83313, '<td valign="top">A bit grainy, which actually works for this image, but there is also what appears to be some slight blur (perhaps camera shake from a low shutter speed?). Also some visible compression artifacts, the result of compressing to a 41k file size, when you could have used up to 300k. Compression kills detail. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit.</td>', 'A bit grainy, which actually works for this image, but there is also what appears to be some slight blur (perhaps camera shake from a low shutter speed?). Also some visible compression artifacts, the result of compressing to a 41k file size, when you could have used up to 300k. Compression kills detail. Check your compression settings when you save your file. Always adjust JPEG compression so that your file size is as large as possible, but within the challenge limit.', '2010-01-06 01:08:16.000000', NULL, 1),
