(5802663, 845060, 42013, '<td valign="top">Great expression--would love a touch more light in her eyes. Well done!</td>', 'Great expression--would love a touch more light in her eyes. Well done!', '2010-01-08 14:15:42.000000', NULL, 1),
(5802664, 844714, 42013, '<td valign="top">Interesting camara angle. Kinda quirky.</td>', 'Interesting camara angle. Kinda quirky.', '2010-01-08 14:16:12.000000', NULL, 1),
