(5803353, 845054, 30791, '<td valign="top">an odd encounter</td>', 'an odd encounter', '2010-01-09 00:02:25.000000', NULL, 1),
(5803553, 843470, 93756, '<td valign="top">I really like abstracts...but this is barely recognizable as a human form. It IS a portrait challenge not a free study or an abstract. I''ll give you the benefit of the doubt that it isn''t just paint on the wall because frankly that''s what it appears but can''t give this any kind of score.</td>', 'I really like abstracts...but this is barely recognizable as a human form. It IS a portrait challenge not a free study or an abstract. I''ll give you the benefit of the doubt that it isn''t just paint on the wall because frankly that''s what it appears but can''t give this any kind of score.', '2010-01-09 08:22:12.000000', NULL, 1),
(5803558, 844378, 93756, '<td valign="top">Love the lighting &amp; the direct look of the subject. Good use of black &amp; white. For a boxer, I want to see his hands in focus too so larger DOF would help here.</td>', 'Love the lighting & the direct look of the subject. Good use of black & white. For a boxer, I want to see his hands in focus too so larger DOF would help here.', '2010-01-09 08:33:38.000000', NULL, 1),
(5803559, 845045, 93756, '<td valign="top">Some more post-processing to make this pop would help. Love the subject and the framing.</td>', 'Some more post-processing to make this pop would help. Love the subject and the framing.', '2010-01-09 08:34:57.000000', NULL, 1),
(5803560, 844962, 93756, '<td valign="top">Close, but would like to see more of her eye. Love the composition.</td>', 'Close, but would like to see more of her eye. Love the composition.', '2010-01-09 08:35:37.000000', NULL, 1),
(5803561, 844335, 93756, '<td valign="top">Nice idea and you got a good expression on her face. Clean up the background and lighten up the highlights.</td>', 'Nice idea and you got a good expression on her face. Clean up the background and lighten up the highlights.', '2010-01-09 08:37:25.000000', NULL, 1),
(5803600, 845064, 101702, '<td valign="top">Gorgeous colouring, great lighting, pretty model. Really nice shot.</td>', 'Gorgeous colouring, great lighting, pretty model. Really nice shot.', '2010-01-09 09:29:45.000000', NULL, 1),
(5803601, 845060, 101702, '<td valign="top">Great shot. I''d personally like a little more light in the eyes, but nonetheless very nice</td>', 'Great shot. I''d personally like a little more light in the eyes, but nonetheless very nice', '2010-01-09 09:30:10.000000', NULL, 1),
(5803604, 844239, 101702, '<td valign="top">Great subject and nice shot, though I think a tighter crop might be more suited</td>', 'Great subject and nice shot, though I think a tighter crop might be more suited', '2010-01-09 09:30:49.000000', NULL, 1),
(5803606, 844168, 101702, '<td valign="top">A great subject, but I''m not sure about the processing - it looks like the guy''s head is floating away from his body, or like it''s a cut and paste job (which I know it is not).</td>', 'A great subject, but I''m not sure about the processing - it looks like the guy''s head is floating away from his body, or like it''s a cut and paste job (which I know it is not).', '2010-01-09 09:33:29.000000', NULL, 1),
