(5803643, 843857, 88204, '<td valign="top">I love the concept. The people reflected in the glass make her seem less lonesly. Also, I''m not a big fan of selective B&amp;W. Still a nice shot.</td>', 'I love the concept. The people reflected in the glass make her seem less lonesly. Also, I''m not a big fan of selective B&W. Still a nice shot.', '2010-01-09 10:29:47.000000', NULL, 1),
(5803645, 844089, 88204, '<td valign="top">Great composition. I like that you include just enough of the background to tell us where he is. Well done. 8</td>', 'Great composition. I like that you include just enough of the background to tell us where he is. Well done. 8', '2010-01-09 10:30:33.000000', NULL, 1),
(5803650, 844335, 88204, '<td valign="top">Wonderful concept. I wish it were all a touch brighter on her face and the picture. As it is by eye is drawn to the upper left corner where it is more white, away from the subject(s). 7 for great concept and interesting subject.</td>', 'Wonderful concept. I wish it were all a touch brighter on her face and the picture. As it is by eye is drawn to the upper left corner where it is more white, away from the subject(s). 7 for great concept and interesting subject.', '2010-01-09 10:33:55.000000', NULL, 1),
