(5806572, 843843, 51747, '<td valign="top">He looks a little too well dressed to be homeless. How about "The Big Issue" as a title?</td>', 'He looks a little too well dressed to be homeless. How about "The Big Issue" as a title?', '2010-01-11 18:45:06.000000', NULL, 1),
(5806573, 845031, 51747, '<td valign="top">Very interesting shot!</td>', 'Very interesting shot!', '2010-01-11 18:46:22.000000', NULL, 1),
