(5808389, 844977, 88204, '<td valign="top">Great concept. Nicely lit. I would love to see his face but I think that goes against your intent. Excellent. 9</td>', 'Great concept. Nicely lit. I would love to see his face but I think that goes against your intent. Excellent. 9', '2010-01-12 23:19:07.000000', NULL, 1),
(5808390, 844663, 88204, '<td valign="top">Beautiful lighting, nice composition, interesting colors. I love the soft focus with sharpness on her face, hand and portions of the guitar. Excellent portrait. 9</td>', 'Beautiful lighting, nice composition, interesting colors. I love the soft focus with sharpness on her face, hand and portions of the guitar. Excellent portrait. 9', '2010-01-12 23:19:11.000000', NULL, 1),
